-- 物品管理重构（v2.5）· 需求2：主题按系统分类重建
-- 备份并清空 tbl_topic，插入 38 条新主题（37 个系统分类主题 + 1 个全量字段主题）
-- 规则（方案 §5.1/§5.2）：
--   主题名 = 分类名；item_cate = 系统分类 id；topic_icon = 分类 icon；
--   fields = 必填三要素（1 图标 / 2 名称 / 3 类别）+ 通用字段（10 标签组 / 5 购入时间 / 6 价格 / 7 数量 / 8 描述 / 12 图片）
--            + 分类特化字段；fields[i].sort 按字段字典（tbl_field_element）sort 位次填写；
--   全量主题 topic_code = full_fields，34 字段全配；
--   topic_type 由 TopicFieldClassifier 同源规则推导（含图片12 → 2 多媒体型；含 3D模型20 → 3 模型型）；
--   mip_profile 由 MipProfileSupport.buildProfileJson 同源规则生成（element 1 图标 url / 2 名称 string，v2.5 口径）；
--   topic_status = 0（启用，App 广场/建档入口可见口径：topicStatus=0）。
-- 幂等：备份表已存在则跳过；主题按固定 id 先删后插，重复执行结果一致。

-- ==================== 备份（可回滚） ====================
CREATE TABLE IF NOT EXISTS `tbl_topic_bak_20261127` AS SELECT * FROM `tbl_topic`;

-- ==================== 清空旧主题 ====================
DELETE FROM `tbl_topic`;

-- ==================== 38 条新主题 ====================
